#!/usr/bin/env bash
# shellcheck disable=SC2155

set -euo pipefail

# Are we running inside a GitLab pipeline?
GITLAB_PIPELINE=$(if [[ -z "${CI_JOB_ID:-}" ]]; then echo false; else echo true; fi)

if [[ ${GITLAB_PIPELINE} = true ]]; then
	BASE_DIR="${CI_PROJECT_DIR}"
else
	BASE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
fi

source "${BASE_DIR}/ansible/functions.sh"


: "${VAULT_SERVER_URL:?Missing value for VAULT_SERVER_URL}"
: "${VAULT_PATH:?Missing value for VAULT_PATH}"
: "${DEPLOY_HOST:?Missing value for DEPLOY_HOST}"

# .vault-token should have been generated by get_vault_token.sh
if [[ ! -f "${BASE_DIR}/.vault-token" ]]; then
	echo "Vault token not generated" >&2
	exit 1
fi

VAULT_TOKEN="$(cat "${BASE_DIR}/.vault-token")"
HC_VAULT_BASE="${VAULT_SERVER_URL}/v1/kv2/data/${VAULT_PATH}"

mkdir -p "${BASE_DIR}/ansible/inventory/group_vars" \
	"${BASE_DIR}/ansible/inventory/host_vars" \
	"${BASE_DIR}/ansible/secrets"

echo "Retrieving Ansible groups for host \"${DEPLOY_HOST}\""
ANSIBLE_GROUPS="$("${BASE_DIR}/ansible/get_ansible_groups_for_host.py" "${DEPLOY_HOST}")"
echo "---> Host \"${DEPLOY_HOST}\" belongs to these groups: ${ANSIBLE_GROUPS:-(none)}"

# Retrieves the JSON data from a HC Vault endpoint and save it to the local file
# system. The file will only be written if the endpoint is valid (no 404) and if
# the JSON data is not empty (at least one key-value pair). The function returns
# normally if either of these conditions is not met. To verify that a secret exists
# and is non-empty, check for the presence of the file.
get_secrets_as_json() {

  # HC Vault Path to secret relative to ${HC_VAULT_BASE}
	local secret="${1:?No secret specified}"
	# File system path relative to ${BASE_DIR}
	local save_as="${2:?No output file specified}"

	local endpoint="${HC_VAULT_BASE}/${secret}"

	echo "Searching for secrets in ${secret}"

	# Get response body __and__ HTTP status code in one CURL request
	# by appending (-w) the HTTP status code to response body
	local body="$(curl -sS -w $'\n%{http_code}' -H "X-Vault-Token: ${VAULT_TOKEN}" "${endpoint}")" || true
	# extracting the status from the response body
	local status="${body##*$'\n'}"
	# and then shaving off the status from body again
	body="${body%$'\n'*}"

	if [[ $status -eq 200 ]]; then
		# Only write a file if there are keys under .data.data
		if jq -e '.data.data | length > 0' > /dev/null 2>&1 <<< "$body"; then
			jq '.data.data' <<< "$body" > "${BASE_DIR}/${save_as}"
			echo "---> Secret saved"
		else
			echo "---> Empty secret"
		fi
	elif [[ $status -eq 404 ]]; then
		echo "---> No secrets there"
	else
		echo "$body" >&2 # E.g. "403 Permission Denied"
		echo >&2
		exit 1
	fi

}

# group_vars
get_secrets_as_json 'cicd/group_vars/all' 'ansible/inventory/group_vars/all.json'
for group in ${ANSIBLE_GROUPS:-}; do
	get_secrets_as_json "cicd/group_vars/${group}" "ansible/inventory/group_vars/${group}.json"
done

# host_vars
get_secrets_as_json 'cicd/host_vars/all' 'ansible/inventory/host_vars/all.json'
get_secrets_as_json "cicd/host_vars/${DEPLOY_HOST}" "ansible/inventory/host_vars/${DEPLOY_HOST}.json"

# AWS credentials
get_secrets_as_json 'tenant/letsencrypt' 'ansible/inventory/host_vars/aws.json'
FULL_PATH="${BASE_DIR}/ansible/inventory/host_vars/aws.json"
[[ ! -f "${FULL_PATH}" ]] && echo "ERROR: Missing AWS credentials" >&2 && exit 1

# SSH key for Ansible
get_secrets_as_json 'cicd/ssh' 'ansible/secrets/ssh.json'
FULL_PATH="${BASE_DIR}/ansible/secrets/ssh.json"
[[ ! -f "${FULL_PATH}" ]] && echo "ERROR: Missing SSH key" >&2 && exit 1

# Generate a true id_ed25519 file using ssh.json
ANSIBLE_DEPLOY_KEY="$(jq -e -r ".ANSIBLE_DEPLOY_KEY" "${FULL_PATH}")"
[[ -z "${ANSIBLE_DEPLOY_KEY:-}" ]] && echo "ERROR: Unable to read SSH key" >&2 && exit 1
echo "${ANSIBLE_DEPLOY_KEY}" >>"${BASE_DIR}/ansible/secrets/id_ed25519"
chmod 0400 "${BASE_DIR}/ansible/secrets/id_ed25519"
